-- Chriz BG Script Engine runtime. Generated by tools/build_runtime.py from the authored
-- modules in this repository; edit those, then rebuild.
-- Builds on Sword Coast Stratagems (DavidW) and Spell Revisions (Demivrgvs, Gibberlings Three).
local factories,loaded={},{}
local function require(name)
  if loaded[name] then return loaded[name] end
  local value=assert(factories[name],'unbundled module')(require)
  loaded[name]=value;return value
end
factories["kernel.manifest"]=function(require)
-- Exact, scalar-only development contract. No resource discovery or native calls.
local M = {}

function M.copy(value)
    local active,nodes={},0
    local function visit(v,depth)
        nodes=nodes+1
        assert(nodes<=16384 and depth<=24,'value-limit')
        local t=type(v)
        if t=='string' then assert(#v<=256 and not v:find('\0',1,true));return v end
        if t=='boolean' or t=='nil' then return v end
        if t=='number' then assert(v==v and v>-math.huge and v<math.huge);return v end
        assert(t=='table' and getmetatable(v)==nil and not active[v],'non-scalar-value')
        active[v]=true
        local result={}
        for k,item in next,v do
            assert(type(k)=='string' or (type(k)=='number' and k%1==0),'invalid-key')
            result[visit(k,depth+1)]=visit(item,depth+1)
        end
        active[v]=nil;return result
    end
    return visit(value,0)
end

function M.equal(a,b)
    if type(a)~='table' or type(b)~='table' then return a==b end
    for k,v in pairs(a) do if not M.equal(v,b[k]) then return false end end
    for k in pairs(b) do if a[k]==nil then return false end end
    return true
end

local function text(v) return type(v)=='string' and #v>0 end
local function record(t,fields)
    if type(t)~='table' then return false end
    local allowed={};for _,k in ipairs(fields) do allowed[k]=true;if t[k]==nil then return false end end
    for k in pairs(t) do if not allowed[k] then return false end end
    return true
end
local function array(t,check,nonempty)
    if type(t)~='table' then return false end
    local count,seen=0,{}
    for k,v in pairs(t) do
        if type(k)~='number' or k<1 or k%1~=0 or not check(v) or seen[v] then return false end
        seen[v]=true;count=count+1
    end
    if nonempty and count==0 then return false end
    for i=1,count do if t[i]==nil then return false end end
    return true
end
local function resref(v) return text(v) and #v<=8 and not v:find('[^A-Z0-9_#-]') end
local extensions={CRE=true,BCS=true,DLG=true,ARE=true,SPL=true,ITM=true,PRO=true,IDS=true,['2DA']=true}
local function resource(v)
    if not text(v) then return false end
    local stem,ext=v:match('^([^%.]+)%.([^%.]+)$')
    return resref(stem) and extensions[ext]==true
end
local function digest(v) return type(v)=='string' and #v==64 and not v:find('[^a-f0-9]') end
local slotNames={override=true,class=true,race=true,general=true,default=true,area=true}

function M.validate(input)
    local ok,m=pcall(M.copy,input)
    if not ok or type(m)~='table' then return nil,'manifest-shape' end
    if m.schemaVersion~=1 then return nil,'manifest-schema' end
    if not text(m.id) or #m.id>64 or not m.id:match('^B%-/[a-z]+/[a-z0-9][a-z0-9%-]*$')
        or m.id:find('%-%-') or m.id:sub(-1)=='-' then return nil,'manifest-id' end
    local domain=m.id:match('^B%-/([^/]+)/')
    if not ((domain=='combat' and m.domain=='CombatIntent') or
        (domain=='worldflow' and m.domain=='WorldFlow')) then return nil,'manifest-domain' end
    if not text(m.version) then return nil,'manifest-version' end
    if not ({C0=true,C1=true,C2=true,C3=true,C4=true})[m.tier] then return nil,'manifest-tier' end
    if m.hashAlgorithm~='sha256' or m.hashVersion~=1 then return nil,'manifest-hash' end
    if not record(m.fallback,{'kind','resources'}) or m.fallback.kind~='legacy' or
        not array(m.fallback.resources,resource,true) then return nil,'manifest-fallback' end
    if not record(m.provenance,{'source','distribution'}) or not text(m.provenance.source) or
        not text(m.provenance.distribution) then return nil,'manifest-provenance' end
    if not array(m.evidence,text,true) then return nil,'manifest-evidence' end
    if not record(m,{'schemaVersion','id','version','domain','tier','profile','epoch',
        'hashAlgorithm','hashVersion','requiredCapabilities','roots','controlClosure','resources',
        'publicState','fallback','provenance','evidence'}) or not text(m.profile) or not text(m.epoch)
        or not array(m.requiredCapabilities,text,true) or not array(m.roots,resource,true)
        or not array(m.controlClosure,resource,false) or type(m.resources)~='table'
        or type(m.publicState)~='table' then return nil,'manifest-shape' end
    for id,r in pairs(m.resources) do
        if not resource(id) or not record(r,{'sha256','dependencies','slots','opaque'}) or
            not digest(r.sha256) or not array(r.dependencies,resource,false) or
            type(r.slots)~='table' or r.opaque~=false then return nil,'manifest-shape' end
        for slot,stem in pairs(r.slots) do
            if not slotNames[slot] or (stem~='' and not resref(stem)) then return nil,'manifest-shape' end
            if stem~='' and not m.resources[stem..'.BCS'] then return nil,'manifest-closure' end
        end
    end
    local reached={}
    local function walk(id)
        if reached[id] then return true end
        local r=m.resources[id];if not r then return false end
        reached[id]=true
        for _,child in ipairs(r.dependencies) do if not walk(child) then return false end end
        for _,stem in pairs(r.slots) do if stem~='' and not walk(stem..'.BCS') then return false end end
        return true
    end
    for _,ids in ipairs({m.roots,m.controlClosure,m.fallback.resources}) do
        for _,id in ipairs(ids) do if not walk(id) then return nil,'manifest-closure' end end
    end
    for id in pairs(m.resources) do if not reached[id] then return nil,'manifest-closure' end end
    for variable,refs in pairs(m.publicState) do
        if not text(variable) or not variable:match('^[A-Z0-9_]+:[A-Z0-9_%-]+$') or
            not record(refs,{'readers','writers'}) or not array(refs.readers,resource,false) or
            not array(refs.writers,resource,false) then return nil,'manifest-public-state' end
        for _,ids in ipairs({refs.readers,refs.writers}) do
            for _,id in ipairs(ids) do if not reached[id] then return nil,'manifest-closure' end end
        end
    end
    return m
end

return M
end
factories["kernel.trace"]=function(require)
local values=require('kernel.manifest')
local M={}
function M.new(capacity)
    assert(type(capacity)=='number' and capacity%1==0 and capacity>=1 and capacity<=4096)
    local rows,nextSlot,size={},1,0
    local fields={'kind','actorKey','adapterId','profile','snapshotVersion','owner','family','reason','tick'}
    local api={}
    function api:record(event)
        local row={}
        for _,field in ipairs(fields) do
            local value=rawget(event,field)
            if value~=nil then
                assert(type(value)=='string' or type(value)=='number','trace scalar required')
                row[field]=values.copy(value)
            end
        end
        rows[nextSlot]=row;nextSlot=nextSlot%capacity+1;size=math.min(size+1,capacity)
    end
    function api:snapshot()
        local result={};local first=(nextSlot-size-1)%capacity+1
        for i=0,size-1 do result[#result+1]=values.copy(rows[(first+i-1)%capacity+1]) end
        return result
    end
    return api
end
return M
end
factories["kernel.hook"]=function(require)
-- BCS handoff gate. A hook block in a creature's script calls claim() each time it is
-- reached: true means the engine performs this round's action, false lets the creature's own
-- blocks run on. Guarded copies of SCS blocks above the hook ask the same question in the same
-- script pass, so the gate answers once per creature and tick and repeats that answer.
-- A creature can carry hooked scripts in several slots (an SCS monster script above SCS's
-- general AI, for example). Slots run from override down to default, and a lower script is
-- reached only after the higher ones let the pass through, so the first hooked script that
-- asks in a pass decides for the creature; the others decline in that pass. The engine also
-- declines when a script that carries no hook sits below the deciding one: an engine round
-- would keep that script from ever running.
-- Nothing here raises to the caller and nothing in it survives a load.
local values=require('kernel.manifest')
local trace=require('kernel.trace')
local M={}
M.families={'mage','priest','fighter','monster'}
local known={};for _,family in ipairs(M.families) do known[family]=true end
local function scalarId(id) return type(id)=='number' and id>=0 and id<4294967296 and id%1==0 end
local function count(value,limit) return type(value)=='number' and value>=0 and value<=limit and value%1==0 end
function M.new(config)
    assert(type(config)=='table' and type(config.now)=='function','clock required')
    local backoff,maxAge=config.backoffTicks or 150,config.maxDecisionAgeTicks or 30
    assert(count(backoff,1e6) and count(maxAge,1e6))
    local enabled=config.enabled~=false
    local families={}
    for family in pairs(known) do
        families[family]=not(type(config.families)=='table' and config.families[family]==false)
    end
    local decide,perform,observe=config.decide,config.perform,config.observe
    assert(observe==nil or type(observe)=='function')
    -- hooked: script resref (lower case) -> family, from the install. below(id, script): the
    -- creature's non-empty script resrefs in the slots after script, or nil when script is not
    -- in its stack.
    local hooked,below
    local function setHooked(t)
        assert(t==nil or type(t)=='table')
        if t==nil then hooked=nil;return end
        hooked={}
        for name,family in pairs(t) do
            if type(name)=='string' and #name>0 then hooked[name:lower()]=family end
        end
    end
    setHooked(config.hooked)
    below=config.below
    assert(below==nil or type(below)=='function')
    local pending,blocked,answers={},{},{}
    local counts={reached=0,repeats=0,claimed=0,acted=0,held=0,skipped=0,stale=0,errors=0,observeErrors=0}
    local declines={}
    local log=trace.new(config.traceCapacity or 64)
    local api={}
    local function bump(t,key) t[key]=math.min((t[key] or 0)+1,4294967295) end
    local function decline(reason) bump(declines,reason);return false end
    local function now()
        local ok,tick=pcall(config.now)
        if ok and count(tick,4294967295) then return tick end
    end
    local function failed(id,family,reason,tick)
        bump(counts,'errors')
        if tick then blocked[id]=tick+backoff end
        log:record({kind='error',actorKey=tostring(id),family=family,reason=reason,tick=tick})
    end
    local function evaluate(id,actor,family,tick,script)
        if not enabled then return decline('disabled') end
        if not known[family] then return decline('unknown-family') end
        if not families[family] then return decline('family-off') end
        if not hooked then return decline('no-registry') end
        if not below then return decline('no-stack') end
        local found,rest=pcall(below,id,script)
        if not found then failed(id,family,'stack-error',tick);return decline('error') end
        if type(rest)~='table' then return decline('no-stack') end
        for _,name in ipairs(rest) do
            if type(name)~='string' or not hooked[name:lower()] then return decline('script-below') end
        end
        -- A load restarts the tick count, so a backoff from before it no longer applies.
        if blocked[id] and tick<blocked[id] and blocked[id]-tick<=backoff then return decline('backoff') end
        blocked[id]=nil
        -- An observer (the fight director's check-in) sees every creature the gate would ask
        -- the decider about; its errors never change the answer.
        if observe and not pcall(function()
            local view=values.copy(actor);view.script=script
            observe(view,family)
        end) then bump(counts,'observeErrors') end
        if not decide then return decline('no-decider') end
        local ok,decision=pcall(function()
            local view=values.copy(actor);view.script=script
            return decide(view,family)
        end)
        if not ok then failed(id,family,'decide-error',tick);return decline('error') end
        if decision==nil then pending[id]=nil;return decline('no-decision') end
        local copied,result=pcall(values.copy,decision)
        if not copied or type(result)~='table' or (result.hold~=nil and result.hold~=true) then
            failed(id,family,'bad-decision',tick);return decline('error')
        end
        pending[id]={decision=result,tick=tick,family=family}
        bump(counts,'claimed')
        log:record({kind='claim',actorKey=tostring(id),family=family,reason=result.hold and 'hold' or 'claimed',tick=tick})
        return true
    end
    -- actor is {id=..., script=...}: the creature and the hooked script that asks.
    function api:claim(actor,family)
        local id=type(actor)=='table' and rawget(actor,'id')
        if not scalarId(id) then return decline('bad-actor') end
        local script=rawget(actor,'script')
        if type(script)~='string' or #script==0 or #script>32 then return decline('bad-script') end
        script=script:lower()
        local tick=now();if not tick then return decline('no-clock') end
        local seen=answers[id]
        if seen and seen.tick==tick then
            if seen.script==script and seen.family==family then bump(counts,'repeats');return seen.result end
            -- Another of the creature's scripts asked first in this pass and decided.
            if seen.script~=script then return decline('lower-script') end
        end
        bump(counts,'reached')
        local result=evaluate(id,actor,family,tick,script)
        answers[id]={tick=tick,script=script,family=family,result=result}
        return result
    end
    -- A decision is performed once, by the hook's response. {hold=true} claims the round
    -- without queueing anything, so the creature's running action is left alone.
    function api:act(actor)
        local id=type(actor)=='table' and rawget(actor,'id')
        if not scalarId(id) then return false,'bad-actor' end
        local p=pending[id];pending[id]=nil
        if not p then return false,'no-pending' end
        local tick=now()
        if not tick or tick<p.tick or tick-p.tick>maxAge then bump(counts,'stale');return false,'stale' end
        if not enabled or not families[p.family] then return false,'disabled' end
        if p.decision.hold then
            bump(counts,'held')
            log:record({kind='act',actorKey=tostring(id),family=p.family,reason='held',tick=tick})
            return true,'held'
        end
        if not perform then failed(id,p.family,'no-performer',tick);return false,'no-performer' end
        local ok,done=pcall(function() return perform(values.copy(actor),values.copy(p.decision)) end)
        -- 'skipped': the decision no longer fits (its target died meanwhile); no error, no backoff.
        if ok and done=='skipped' then
            bump(counts,'skipped')
            log:record({kind='act',actorKey=tostring(id),family=p.family,reason='skipped',tick=tick})
            return false,'skipped'
        end
        if not ok or done~=true then failed(id,p.family,ok and 'not-performed' or 'perform-error',tick);return false,'error' end
        bump(counts,'acted')
        log:record({kind='act',actorKey=tostring(id),family=p.family,reason='performed',tick=tick})
        return true
    end
    -- Whether the gate is on for a family right now (for helpers that act outside a claim).
    function api:allows(family) return enabled and known[family]==true and families[family]==true end
    function api:setEnabled(value)
        assert(type(value)=='boolean');enabled=value;answers={}
        if not value then pending={} end
    end
    function api:setFamily(family,value)
        assert(known[family] and type(value)=='boolean');families[family]=value;answers={}
        if not value then for id,p in pairs(pending) do if p.family==family then pending[id]=nil end end end
    end
    function api:setDecider(fn) assert(fn==nil or type(fn)=='function');decide=fn;pending,answers={},{} end
    function api:setPerformer(fn) assert(fn==nil or type(fn)=='function');perform=fn;pending,answers={},{} end
    function api:setHooked(t) setHooked(t);answers={} end
    function api:invalidate() pending,blocked,answers={},{},{} end
    function api:inspect()
        local open=0;for _ in pairs(pending) do open=open+1 end
        local scripts=0;for _ in pairs(hooked or {}) do scripts=scripts+1 end
        return {enabled=enabled,families=values.copy(families),counts=values.copy(counts),
            declines=values.copy(declines),pending=open,hookedScripts=hooked and scripts or nil,
            trace=log:snapshot()}
    end
    return api
end
return M
end
factories["kernel.rng"]=function(require)
-- Independent Park-Miller streams for reproducible host simulations.
local M = {}
local MODULUS = 2147483647
local MULTIPLIER = 16807
local SAMPLE_COUNT = MODULUS - 1
local MAX_EXACT_INTEGER = 9007199254740991

local function integer(value)
    return type(value) == 'number' and value == value and
        value < math.huge and value > -math.huge and
        value == math.floor(value) and
        value >= -MAX_EXACT_INTEGER and value <= MAX_EXACT_INTEGER
end

function M.new(seed)
    assert(integer(seed) and seed >= 1 and seed < MODULUS,
        'seed must be an integer from 1 to 2147483646')
    local current = seed
    return {
        state = function()
            return current
        end,
        nextInt = function(_, minimum, maximum)
            assert(integer(minimum) and integer(maximum) and minimum <= maximum,
                'range endpoints must be ordered exact integers')
            local width = maximum - minimum + 1
            assert(width >= 1 and width <= SAMPLE_COUNT,
                'range width exceeds generator sample count')

            local accepted = math.floor(SAMPLE_COUNT / width) * width
            local sample
            repeat
                -- The product is < 2^53, so Lua doubles represent it exactly.
                current = (current * MULTIPLIER) % MODULUS
                sample = current - 1
            until sample < accepted
            return minimum + (sample % width)
        end,
    }
end

return M
end
factories["combat-intent.spells"]=function(require)
-- What a spell or item ability does, read from its real effects (design step 2). Records are
-- plain tables with the fields of tools/ie_resources.py (in game: adapters/eeex/resources.lua).
-- lookup(kind, key) returns another record: 'SPL', 'ITM' or 'EFF' by resref, 'PRO' by the
-- ability's projectile number. Spells delivered through other spells or EFF files are followed
-- with depth, cycle and size limits. Nothing here raises: odd or missing data is reported in
-- the result (partial, reasons, unknown opcodes), and the caller skips what it cannot use.
--
-- roles is everything the spell can do to anyone. Some effects reach only one kind of
-- creature: what 177 or 283 deliver with an IDS entry, a hold that names a creature type, what
-- 326 applies to creatures that meet a SPLPROT row. Those kinds are the spell's conditions, and
-- M.view gives the roles for one creature by which of them it meets: an extra for trolls counts
-- only on trolls, and a conditional immunity (Spell Revisions spares elves its charms and the
-- undead its fear; most of its spells first make creatures in a given spell state immune) takes
-- out what follows it.
local M={}
-- SCS's troll chains and SR's Greater Command go more than eight deliveries deep.
M.limits={depth=12,effects=2048}

local DAMAGE={[0]='crushing',[1]='acid',[2]='cold',[4]='electricity',[8]='fire',[16]='piercing',
    [32]='poison',[64]='magic',[128]='missile',[256]='slashing',[512]='magicfire',[1024]='magiccold',
    [2048]='stunning'}
local SAVES={{1,'spell'},{2,'breath'},{4,'death'},{8,'wand'},{16,'poly'}}
local RESIST={[27]='acid',[28]='cold',[29]='electricity',[30]='fire',[31]='magic',[84]='magicfire',
    [85]='magiccold',[86]='slashing',[87]='crushing',[88]='piercing',[89]='missile',[173]='poison'}
local STATS={[6]='charisma',[10]='constitution',[15]='dexterity',[19]='intelligence',[44]='strength',
    [49]='wisdom',[97]='strength'}
local TOHIT={[54]=true,[167]=true,[278]=true,[284]=true,[288]=true,[305]=true,[306]=true}
local WEAPON_DAMAGE={[73]=true,[285]=true,[286]=true,[289]=true}
local SAVE_MODS={[33]=true,[34]=true,[35]=true,[36]=true,[37]=true,[325]=true,[346]=true}
-- Opcodes that use the dice fields for an amount; elsewhere they are a level range.
local DICE_AMOUNT={[12]=true,[17]=true,[18]=true,[25]=true,[98]=true,[218]=true}
-- Graphics, sounds, text, scripting state and bookkeeping: no role.
local NEUTRAL={}
for _,op in ipairs({7,8,9,23,41,50,51,52,53,56,57,61,63,64,66,71,72,82,94,95,96,99,103,104,105,
    106,107,108,112,114,115,117,122,123,125,138,139,140,141,142,144,147,149,150,152,155,156,164,
    169,170,172,174,180,181,182,183,184,186,187,190,192,194,195,196,215,225,237,239,240,243,
    244,245,251,252,253,254,255,262,263,265,267,268,269,271,275,276,277,279,281,282,287,290,291,
    293,294,295,296,298,300,302,307,308,309,311,312,313,315,319,320,323,327,328,330,336,338,339,
    340,341,342,347,348,349,350,351,352,353,354,355,356,357,358,359,360,361,362,363,364,365,367,
    21,59,90,91,92,171,233,266,321}) do NEUTRAL[op]=true end
-- 321 and 266 remove the effects or protections of one named resource: SCS and SR use them
-- to refresh their own helpers, so they are bookkeeping, not dispelling.
M.neutral=NEUTRAL

local function number(v) return type(v)=='number' and v==v and v>-math.huge and v<math.huge end
-- Readers may return a dword unsigned; some opcodes store a signed amount in it.
local function s32(v) if v>=2^31 then return v-2^32 end return v end
local function chance(e)
    local hi,lo=math.min(e.prob1,100),math.max(e.prob2,0)
    if hi<lo then return 0 end
    return (hi-lo+1)/101
end
local function seconds(e)
    local timing=e.timing%256
    if timing==1 or timing==4 or timing==7 or timing==9 then return 'permanent' end
    if timing==2 or timing==5 or timing==8 then return 'equipped' end
    if timing==10 then return e.duration/15 end
    return e.duration
end
local function average(dice,sides) if dice>0 and sides>0 then return dice*(sides+1)/2 end return 0 end
local function saveNames(bits)
    local names
    for _,pair in ipairs(SAVES) do
        if math.floor(bits/pair[1])%2==1 then names=names or {};names[pair[2]]=true end
    end
    return names
end
-- Timings that apply an effect after its duration: delayed limited, permanent, while equipped.
local DELAYED={[3]=true,[4]=true,[5]=true}
-- Effects that come more than this many seconds after the cast (Spell Revisions' Haste casts its
-- fatigue when it ends) are kept apart in c.later: they are not what the spell does now.
M.laterThan=6
local function delay(e) return DELAYED[e.timing%256] and math.max(e.duration,0) or 0 end
local function longer(a,b)
    if a==nil then return b end
    if b==nil then return a end
    if a=='permanent' or b=='permanent' then return 'permanent' end
    if a=='equipped' or b=='equipped' then return 'equipped' end
    return math.max(a,b)
end

-- One effect's contribution to a role: who gets it, how likely, saves, level range, duration.
-- An area role also names the side filters of the areas it came through: 'allies', 'enemies' or
-- 'all' (the delivering area's, else the spell's own).
local function add(c,name,who,e,p)
    local r=c.roles[name]
    if not r then r={who={},kinds={},chance=0,power=0};c.roles[name]=r end
    r.who[who]=true
    if who=='area' then
        r.filters=r.filters or {}
        r.filters[c.filter or (c.area and c.area.filter) or 'all']=true
    end
    r.chance=math.max(r.chance,p)
    r.power=math.max(r.power,e.power)
    local saves=saveNames(e.save)
    if saves then
        r.save=r.save or {}
        for s in pairs(saves) do r.save[s]=true end
        if r.saveBonus==nil or e.saveBonus<r.saveBonus then r.saveBonus=e.saveBonus end
    end
    if not DICE_AMOUNT[e.opcode] then
        if e.dice>0 then r.maxLevel=math.min(r.maxLevel or e.dice,e.dice) end
        if e.sides>0 then r.minLevel=math.max(r.minLevel or e.sides,e.sides) end
    end
    r.duration=longer(r.duration,seconds(e))
    return r
