local function deliver(c,state,e,where,depth,p)
    local inherit,wait=c.inherit,c.delay
    if saveNames(e.save) then c.inherit={save=e.save,saveBonus=e.saveBonus} end
    c.delay=(wait or 0)+delay(e)
