    c.owner=owner
    -- Each record walked is a node; a conditional protection from it cuts what follows inside.
    if key then
        c.nodes[#c.nodes+1]={res=key:match('^SPL:(.+)$'),parent=parent}
        c.node=#c.nodes
    end
    if type(effects)=='table' then
        for _,e in ipairs(effects) do
            state.count=state.count+1
            if state.count>M.limits.effects then c.partial=true;c.reasons['too-many-effects']=true;break end
            if type(e)~='table' or not valid(e) then c.partial=true;c.reasons['bad-effect']=true
